{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-seq0/frozen/held-out/play/users/u034/system/state/workspace/programs/task-47585d04.py",
 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # A 5-colored line frames the region; copy the adjacent non-5 color pattern
    # along the perpendicular direction to fill the framed rectangle.
    for r in range(h):
        run=[c for c,v in enumerate(grid[r]) if v==5]
        if len(run)>=2:
            # horizontal frame: nearby colored pattern extending to its right
            # use nonzero non-5 cells on row, then copy their sequence vertically
            pat=[(c,grid[r][c]) for c in range(w) if grid[r][c] not in (0,5)]
            if pat:
                lo=min(p for p,v in pat); hi=max(p for p,v in pat)
                c0=min(run); r0=min((rr for rr in range(h) if grid[rr][c0]==5),default=r)
                r1=max((rr for rr in range(h) if grid[rr][c0]==5),default=r)
                for rr in range(r0,r1+1):
                    for c,v in pat: out[rr][c]=v
                return out
    # Vertical line with a colored horizontal template at one end: propagate template.
    for c in range(w):
        rr=[r for r in range(h) if grid[r][c]==5]
        if len(rr)>=2:
            for r in range(h):
                pat=[(cc,grid[r][cc]) for cc in range(w) if grid[r][cc] not in (0,5)]
                if pat:
                    lo=min(cc for cc,v in pat); hi=max(cc for cc,v in pat)
                    # Fill between end template and opposite end of the 5-bar.
                    start=min(rr); end=max(rr)
                    for r2 in range(start,end+1):
                        for cc,v in pat: out[r2][cc]=v
                    return out
    return out
"
}

