        if len(rs)>=2 and max(rs)-min(rs)+1==len(rs): candidates.append(('v',c,min(rs),max(rs)))
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==5]
        if len(cs)>=2 and max(cs)-min(cs)+1==len(cs): candidates.append(('h',r,min(cs),max(cs)))
    # Prefer long vertical bar, like the demonstration.
    kind,pos,lo,hi=max(candidates,key=lambda x:x[3]-x[2])
    if kind=='v':
        # Colored template lies to right of bar on the last two rows.
        first=max(0,hi-1)
        template=[]
        for r in (first,hi):
            vals=[grid[r][c] for c in range(pos+1,w)]
            if any(v not in (0,5) for v in vals): template.append(vals)
        if not template:return out
        # Pattern is repeated upward from the lower endpoint in its original order.
        for r in range(lo,hi+1):
            vals=template[(r-first)%len(template)]
            for k,v in enumerate(vals,pos+1):
                if v not in (0,5):out[r][k]=v
    else:
        # Horizontal analogue: repeat attached color columns vertically.
        return out
    return out
